    if (event == piecerec::kPePlaced) { w->removed = 0; w->moving = 0; w->snapHave = 0; w->holder = 0; w->capHave = 0; w->capOwed = 0; }   /* a new placement at the key (review fold: its old capture is not the new piece's) */
    PcrMarkW(*w, key, event);
