    if (BdReadState(b, &prog, &need, &complete, &dism, &destroyed) == 0 || complete == 0) return 0;
    if (BdPowerNetPod(b) == 0) { ++(offNet != 0 ? *offNet : g_pwOffNetRelink); return 0; }
