    if (list == 0 || kBdNearestRva == 0) { *faulted = 1; return 0; }
    __try { return ((BdNearestFn)(uintptr_t)AddrAbs(kBdNearestRva))(list, pos, faction, 0, 0, kBdNearestKindAny); }
    __except (EXCEPTION_EXECUTE_HANDLER) { *faulted = 1; return 0; }
